class Solution {
    private static class State{
        TreeNode node;
        long index;
        State(TreeNode node,long index){
            this.node=node;
            this.index=index;
        }
    }
    public int widthOfBinaryTree(TreeNode root){
        Queue<State> queue=new ArrayDeque<>();
        queue.offer(new State(root,0));
        long best=0;
        while(!queue.isEmpty()){
            int size=queue.size();
            long base=queue.peek().index,first=0,last=0;
            for(int i=0;i<size;i++){
                State state=queue.poll();
                long index=state.index-base;
                if(i==0)first=index;
                if(i==size-1)last=index;
                if(state.node.left!=null)queue.offer(new State(state.node.left,index*2));
                if(state.node.right!=null)queue.offer(new State(state.node.right,index*2+1));
            }
            best=Math.max(best,last-first+1);
        }
        return(int)best;
    }
}

code.kotlin:
class Solution {
    private data class State(val node:TreeNode,val index:Long);
    fun widthOfBinaryTree(root:TreeNode?):Int{
        val queue=java.util.ArrayDeque<State>();
        queue.add(State(root!!,0));
        var best=0L;
        while(queue.isNotEmpty()){
            val size=queue.size;
            val base=queue.peek().index;
            var first=0L;
            var last=0L;
            repeat(size){
                val state=queue.remove();
                val index=state.index-base;
                if(it==0)first=index;
                if(it==size-1)last=index;
                state.node.left?.let{
                    node->queue.add(State(node,index*2))
                };
                state.node.right?.let{
                    node->queue.add(State(node,index*2+1))
                }
            };
            best=maxOf(best,last-first+1)
        };
        return best.toInt()
    }
}

